{

    internal InnerGatewayTargetInferenceConnectorTargetConfigurationFactory ConnectorFactory { get; set; }

    internal InnerGatewayTargetInferenceProviderTargetConfigurationFactory ProviderFactory { get; set; }

    protected override Humidifier.BedrockAgentCore.GatewayTargetTypes.InferenceTargetConfiguration Create()
    {
        var inferenceTargetConfigurationResult = CreateInferenceTargetConfiguration();
        factoryAction?.Invoke(inferenceTargetConfigurationResult);

        return inferenceTargetConfigurationResult;
    }

    private Humidifier.BedrockAgentCore.GatewayTargetTypes.InferenceTargetConfiguration CreateInferenceTargetConfiguration()
    {
        var inferenceTargetConfigurationResult = new Humidifier.BedrockAgentCore.GatewayTargetTypes.InferenceTargetConfiguration();

        return inferenceTargetConfigurationResult;
    }
    public override void CreateChildren(Humidifier.BedrockAgentCore.GatewayTargetTypes.InferenceTargetConfiguration result)
    {
        base.CreateChildren(result);

        result.Connector ??= ConnectorFactory?.Build();
        result.Provider ??= ProviderFactory?.Build();
    }

} // End Of Class

